package com.example.data

import com.example.model.SurahVerse

internal val surahYasinPart2: List<SurahVerse> = listOf(
  SurahVerse(43, "وَاِنْ نَّشَأْ نُغْرِقْهُمْ فَلَا صَرِيْخَ لَهُمْ وَلَا هُمْ يُنْقَذُوْنَۙ", "Wa in nasya' nughriqhum falā sharīkha lahum wa lā hum yunqadzūn", "Jika Kami menghendaki, Kami dapat menenggelamkan mereka tanpa ada penolong yang mampu menyelamatkan."),
  SurahVerse(44, "اِلَّا رَحْمَةً مِّنَّا وَمَتَاعًا اِلٰى حِيْنٍ", "Illā rahmatam minnā wa matā'an ilā hīn", "Melainkan karena rahmat dari Kami dan kesenangan hidup hingga batas waktu tertentu."),
  SurahVerse(45, "وَاِذَا قِيْلَ لَهُمُ اتَّقُوْا مَا بَيْنَ اَيْدِيْكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُوْنَ", "Wa idzā qīla lahumut-taqū mā baina aidīkum wa mā khalfakum la'allakum turhamūn", "Apabila mereka diingatkan agar bertakwa atas urusan dunia dan akhirat supaya dirahmati, mereka berpaling."),
  SurahVerse(46, "وَمَا تَأْتِيْهِمْ مِّنْ اٰيَةٍ مِّنْ اٰيٰتِ رَبِّهِمْ اِلَّا كَانُوْا عَنْهَا مُعْرِضِيْنَ", "Wa mā ta'tīhim min āyatim min āyāti rabbihim illā kānū 'anhā mu'ridhīn", "Setiap kali datang ayat-ayat Tuhan kepada mereka, mereka selalu mengabaikannya."),
  SurahVerse(47, "وَاِذَا قِيْلَ لَهُمْ اَنْفِقُوْا مِمَّا رَزَقَكُمُ اللّٰهُ ۙقَالَ الَّذِيْنَ كَفَرُوْا لِلَّذِيْنَ اٰمَنُوْٓا اَنُطْعِمُ مَنْ لَّوْ يَشَاۤءُ اللّٰهُ اَطْعَمَهٗٓ ۖاِنْ اَنْتُمْ اِلَّا فِيْ ضَلٰلٍ مُّبِيْنٍ", "Wa idzā qīla lahum anfiqū mimmā razaqakumullāhu qālal-ladzīna kafarū lilladzīna āmanū anuth'imu mal lau yasyā'ullāhu ath'amahū in antum illā fī dhalālim mubīn", "Saat diajak menafkahkan sebagian rezeki Allah, orang-orang ingkar justru menolak memberi makan orang yang membutuhkan."),
  SurahVerse(48, "وَيَقُوْلُوْنَ مَتٰى هٰذَا الْوَعْدُ اِنْ كُنْتُمْ صٰدِقِيْنَ", "Wa yaqūlūna matā hādzal-wa'du in kuntum shādiqīn", "Mereka pun menantang dengan bertanya kapan janji hari kebangkitan itu terjadi jika kalian benar."),
  SurahVerse(49, "مَا يَنْظُرُوْنَ اِلَّا صَيْحَةً وَّاحِدَةً تَأْخُذُهُمْ وَهُمْ يَخِصِّمُوْنَ", "Mā yanzhurūna illā shaihataw wāhidatan ta'khudzuhum wa hum yakhishshimūn", "Yang mereka tunggu hanyalah satu tiupan sangkakala yang datang tiba-tiba saat mereka masih bertengkar."),
  SurahVerse(50, "فَلَا يَسْتَطِيْعُوْنَ تَوْصِيَةً وَّلَآ اِلٰٓى اَهْلِهِمْ يَرْجِعُوْنَ", "Falā yastathī'ūna taushiyataw wa lā ilā ahlihim yarji'ūn", "Ketika itu mereka tidak sempat berwasiat dan tidak pula dapat pulang kepada keluarga mereka."),
  SurahVerse(51, "وَنُفِخَ فِى الصُّوْرِ فَاِذَا هُمْ مِّنَ الْاَجْدَاثِ اِلٰى رَبِّهِمْ يَنْسِلُوْنَ", "Wa nufikha fis-shūri fa'idzā hum minal-ajdātsi ilā rabbihim yansilūn", "Ditiuplah sangkakala sehingga mereka keluar bergegas dari kubur menuju Tuhan mereka."),
  SurahVerse(52, "قَالُوْا يٰوَيْلَنَا مَنْۢ بَعَثَنَا مِنْ مَّرْقَدِنَا ۜهٰذَا مَا وَعَدَ الرَّحْمٰنُ وَصَدَقَ الْمُرْسَلُوْنَ", "Qālū yā wailanā mam ba'atsanā mim marqadinā, hādzā mā wa'adar-rahmānu wa shadaqal-mursalūn", "Mereka berseru siapa yang membangkitkan kami dari tidur kami; inilah janji Tuhan yang benar sesuai sabda para rasul."),
  SurahVerse(53, "اِنْ كَانَتْ اِلَّا صَيْحَةً وَّاحِدَةً فَاِذَا هُمْ جَمِيْعٌ لَّدَيْنَا مُحْضَرُوْنَ", "In kānat illā shaihataw wāhidatan fa'idzā hum jamī'ul ladainā muhdharūn", "Sekali teriakan saja, seketika itu seluruh manusia dikumpulkan di hadapan Kami."),
  SurahVerse(54, "فَالْيَوْمَ لَا تُظْلَمُ نَفْسٌ شَيْـًٔا وَّلَا تُجْزَوْنَ اِلَّا مَا كُنْتُمْ تَعْمَلُوْنَ", "Fal-yauma lā tuzhlamu nafsun syai'aw wa lā tujzauna illā mā kuntum ta'malūn", "Pada hari itu tidak ada seorang pun yang dizalimi, dan setiap jiwa dibalas sesuai perbuatannya."),
  SurahVerse(55, "اِنَّ اَصْحٰبَ الْجَنَّةِ الْيَوْمَ فِيْ شُغُلٍ فٰكِهُوْنَ ۚ", "Inna ash-hābal-jannatil-yauma fī syughulin fākihūn", "Sungguh penghuni surga pada hari itu berada dalam kesibukan yang penuh kegembiraan."),
  SurahVerse(56, "هُمْ وَاَزْوَاجُهُمْ فِيْ ظِلٰلٍ عَلَى الْاَرَاۤىِٕكِ مُتَّكِـُٔوْنَ ۚ", "Hum wa azwājuhum fī zhilālin 'alal-arā'iki muttaki'ūn", "Mereka dan pasangan mereka bersandar di atas dipan-dipan indah di bawah naungan teduh."),
  SurahVerse(57, "لَهُمْ فِيْهَا فَاكِهَةٌ وَّلَهُمْ مَّا يَدَّعُوْنَ ۚ", "Lahum fīhā fākihatuw wa lahum mā yadda'ūn", "Di surga tersedia beragam buah-buahan dan apa saja yang mereka inginkan."),
  SurahVerse(58, "سَلٰمٌۗ قَوْلًا مِّنْ رَّبٍّ رَّحِيْمٍ", "Salām, qaulam mir rabbir rahīm", "Ucapan salam sejahtera dari Tuhan Yang Maha Penyayang."),
  SurahVerse(59, "وَامْتَازُوا الْيَوْمَ اَيُّهَا الْمُجْرِمُوْنَ", "Wamtāzul-yauma ayyuhal-mujrimūn", "Dan dipisahkanlah pada hari itu orang-orang yang berbuat durhaka."),
  SurahVerse(60, "اَلَمْ اَعْهَدْ اِلَيْكُمْ يٰبَنِيْٓ اٰدَمَ اَنْ لَّا تَعْبُدُوا الشَّيْطٰنَۚ اِنَّهٗ لَكُمْ عَدُوٌّ مُّبِيْنٌ", "Alam a'had ilaikum yā banī ādama al lā ta'budusy-syaithān, innahū lakum 'aduwwum mubīn", "Bukankah Aku telah berpesan wahai anak cucu Adam agar kalian tidak mengikuti setan yang menjadi musuh nyata?"),
  SurahVerse(61, "وَاَنِ اعْبُدُوْنِيْ ۗهٰذَا صِرَاطٌ مُّسْتَقِيْمٌ", "Wa ani'budūnī, hādzā shirātum mustaqīm", "Dan hendaklah kalian menyembah-Ku semata, karena inilah jalan yang lurus."),
  SurahVerse(62, "وَلَقَدْ اَضَلَّ مِنْكُمْ جِبِلًّا كَثِيْرًا ۗاَفَلَمْ تَكُوْنُوْا تَعْقِلُوْنَ", "Wa laqad adhalla minkum jibillan katsīrā, afalam takūnū ta'qilūn", "Sungguh setan telah menyesatkan banyak golongan di antara kalian, maka tidakkah kalian menggunakan akal?"),
  SurahVerse(63, "هٰذِهٖ جَهَنَّمُ الَّتِيْ كُنْتُمْ تُوْعَدُوْنَ", "Hādzihī jahannamul-latī kuntum tū'adūn", "Inilah neraka Jahanam yang dahulu telah diperingatkan kepada kalian."),
  SurahVerse(64, "اِصْلَوْهَا الْيَوْمَ بِمَا كُنْتُمْ تَكْفُرُوْنَ", "Ishlauhal-yauma bimā kuntum takfurūn", "Rasakanlah panasnya hari ini sebagai balasan atas kekufuran kalian."),
  SurahVerse(65, "اَلْيَوْمَ نَخْتِمُ عَلٰٓى اَفْوَاهِهِمْ وَتُكَلِّمُنَآ اَيْدِيْهِمْ وَتَشْهَدُ اَرْجُلُهُمْ بِمَا كَانُوْا يَكْسِبُوْنَ", "Al-yauma nakhtimu 'alā afwāhihim wa tukallimunā aidīhim wa tasyhadu arjuluhum bimā kānū yaksibūn", "Pada hari itu Kami kunci mulut mereka, lalu tangan mereka berbicara dan kaki mereka bersaksi atas semua perbuatan."),
  SurahVerse(66, "وَلَوْ نَشَاۤءُ لَطَمَسْنَا عَلٰٓى اَعْيُنِهِمْ فَاسْتَبَقُوا الصِّرَاطَ فَاَنّٰى يُبْصِرُوْنَ", "Wa lau nasyā'u lathamasnā 'alā a'yunihim fastabaqus-shirātha fa'annā yubshirūn", "Jika Kami kehendaki, Kami dapat menghapus penglihatan mereka sehingga mereka tidak tahu arah jalan."),
  SurahVerse(67, "وَلَوْ نَشَاۤءُ لَمَسَخْنٰهُمْ عَلٰى مَكَانَتِهِمْ فَمَا اسْتَطَاعُوْا مُضِيًّا وَّلَا يَرْجِعُوْنَ", "Wa lau nasyā'u lamasakhnāhum 'alā makānatihim famastathā'ū mudhiyyaw wa lā yarji'ūn", "Jika Kami kehendaki pula, Kami ubah keadaan mereka di tempatnya sehingga tidak mampu melangkah maju atau mundur."),
  SurahVerse(68, "وَمَنْ نُّعَمِّرْهُ نُنَكِّسْهُ فِى الْخَلْقِۗ اَفَلَا يَعْقِلُوْنَ", "Wa man nu'ammirhu nunakkishu fil-khalq, afalā ya'qilūn", "Siapa yang Kami panjangkan umurnya akan Kami kembalikan kekuatannya menjadi lemah seperti semula."),
  SurahVerse(69, "وَمَا عَلَّمْنٰهُ الشِّعْرَ وَمَا يَنْۢبَغِيْ لَهٗ ۗاِنْ هُوَ اِلَّا ذِكْرٌ وَّقُرْاٰنٌ مُّبِيْنٌۙ", "Wa mā 'allamnāhusy-syi'ra wa mā yambaghī lah, in huwa illā dzikruw wa qur'ānum mubīn", "Kami tidak mengajarkan syair kepada Nabi Muhammad; kitab ini hanyalah pengingat dan Al-Qur'an yang memberi penerangan."),
  SurahVerse(70, "لِّيُنْذِرَ مَنْ كَانَ حَيًّا وَّيَحِقَّ الْقَوْلُ عَلَى الْكٰفِرِيْنَ", "Liyundzira man kāna hayyaw wa yahiqqal-qaulu 'alal-kāfirīn", "Supaya memberi peringatan kepada orang yang hatinya hidup dan menegakkan ketetapan bagi yang ingkar."),
  SurahVerse(71, "اَوَلَمْ يَرَوْا اَنَّا خَلَقْنَا لَهُمْ مِّمَّا عَمِلَتْ اَيْدِيْنَآ اَنْعَامًا فَهُمْ لَهَا مٰلِكُوْنَ", "Awalam yarau annā khalaqnā lahum mimmā 'amilat aidīnā an'āman fahum lahā mālikūn", "Tidakkah mereka melihat bahwa Kami ciptakan hewan ternak dari kekuasaan Kami untuk mereka miliki?"),
  SurahVerse(72, "وَذَلَّلْنٰهَا لَهُمْ فَمِنْهَا رَكُوْبُهُمْ وَمِنْهَا يَأْكُلُوْنَ", "Wa dzallalnāhā lahum faminhā rakūbuhum wa minhā ya'kulūn", "Kami tundukkan hewan-hewan itu sehingga sebagian menjadi tunggangan dan sebagian lagi untuk dimakan."),
  SurahVerse(73, "وَلَهُمْ فِيْهَا مَنَافِعُ وَمَشَارِبُۗ اَفَلَا يَشْكُرُوْنَ", "Wa lahum fīhā manāfi'u wa masyārib, afalā yasykurūn", "Mereka juga memperoleh beragam manfaat dan minuman susu darinya, maka mengapa tidak bersyukur?"),
  SurahVerse(74, "وَاتَّخَذُوْا مِنْ دُوْنِ اللّٰهِ اٰلِهَةً لَّعَلَّهُمْ يُنْصَرُوْنَ ۗ", "Wattakhadzū min dūnillāhi ālihatal la'allahum yunsharūn", "Namun mereka mengambil sesembahan selain Allah dengan harapan mendapat pertolongan."),
  SurahVerse(75, "لَا يَسْتَطِيْعُوْنَ نَصْرَهُمْۙ وَهُمْ لَهُمْ جُنْدٌ مُّحْضَرُوْنَ", "Lā yastathī'ūna nashrahum wa hum lahum jundum muhdharūn", "Berhala-berhala itu tak sanggup menolong mereka, padahal mereka justru menjadi pengawal yang sia-sia."),
  SurahVerse(76, "فَلَا يَحْزُنْكَ قَوْلُهُمْ ۘاِنَّا نَعْلَمُ مَا يُسِرُّوْنَ وَمَا يُعْلِنُوْنَ", "Falā yahzunka qauluhum, innā na'lamu mā yusirrūna wa mā yu'linūn", "Janganlah engkau bersedih atas ucapan mereka karena Kami mengetahui segala yang mereka rahasiakan dan tampakkan."),
  SurahVerse(77, "اَوَلَمْ يَرَ الْاِنْسَانُ اَنَّا خَلَقْنٰهُ مِنْ نُّطْفَةٍ فَاِذَا هُوَ خَصِيْمٌ مُّبِيْنٌ", "Awalam yaral-insānu annā khalaqnāhu min nuthfatin fa'idzā huwa khashīmum mubīn", "Tidakkah manusia menyadari bahwa Kami menciptakannya dari setetes air yang hina lalu ia menjadi pembantah nyata?"),
  SurahVerse(78, "وَضَرَبَ لَنَا مَثَلًا وَّنَسِيَ خَلْقَهٗۗ قَالَ مَنْ يُّحْيِ الْعِظَامَ وَهِيَ رَمِيْمٌ", "Wa dharaba lanā matsalaw wa nasiya khalqah, qāla may yuhyil-'izhāma wa hiya ramīm", "Ia lupa asal penciptaannya lalu bertanya siapa yang sanggup menghidupkan tulang belulang yang telah hancur."),
  SurahVerse(79, "قُلْ يُحْيِيْهَا الَّذِيْٓ اَنْشَاَهَآ اَوَّلَ مَرَّةٍ ۗوَهُوَ بِكُلِّ خَلْقٍ عَلِيْمٌ ۙ", "Qul yuhyīhal-ladzī ansya'ahā awwala marrah, wa huwa bikulli khalqin 'alīm", "Katakanlah yang menghidupkannya adalah Tuhan yang menciptakannya pertama kali dan Dia Maha Mengetahui segala ciptaan."),
  SurahVerse(80, "ۨالَّذِيْ جَعَلَ لَكُمْ مِّنَ الشَّجَرِ الْاَخْضَرِ نَارًا فَاِذَآ اَنْتُمْ مِّنْهُ تُوْقِدُوْنَ", "Alladzī ja'ala lakum minasy-syajaril-akhdhari nāran fa'idzā antum minhu tūqidūn", "Dialah yang menjadikan api bagi kalian dari pepohonan hijau sehingga kalian menyalakannya."),
  SurahVerse(81, "اَوَلَيْسَ الَّذِيْ خَلَقَ السَّمٰوٰتِ وَالْاَرْضَ بِقٰدِرٍ عَلٰٓى اَنْ يَّخْلُقَ مِثْلَهُمْ ۗبَلٰى وَهُوَ الْخَلّٰقُ الْعَلِيْمُ", "Awalaisal-ladzī khalaqas-samāwāti wal-ardha biqādirin 'alā ay yakhluqa mitslahum, balā wa huwal-khallāqul-'alīm", "Bukankah Pencipta langit dan bumi itu Maha Kuasa menciptakan kembali yang serupa dengan mereka? Benar, Dia Maha Pencipta lagi Maha Mengetahui."),
  SurahVerse(82, "اِنَّمَآ اَمْرُهٗٓ اِذَآ اَرَادَ شَيْـًٔا اَنْ يَّقُوْلَ لَهٗ كُنْ فَيَكُوْنُ", "Innamā amruhū idzā arāda syai'an ay yaqūla lahū kun fayakūn", "Sesungguhnya urusan-Nya apabila menghendaki sesuatu hanyalah berfirman 'Jadilah', maka jadilah ia."),
  SurahVerse(83, "فَسُبْحٰنَ الَّذِيْ بِيَدِهٖ مَلَكُوْتُ كُلِّ شَيْءٍ وَّاِلَيْهِ تُرْجَعُوْنَ", "Fasubhānal-ladzī biyadihī malakūtu kulli syai'iw wa ilaihi turja'ūn", "Maka Maha Suci Allah yang di tangan-Nya kekuasaan atas segala sesuatu, dan hanya kepada-Nya kalian semua dikembalikan."),
)
